};

MetadataType inline MetadataType_from_ustring(const ustring str)
{
	if(str.compare("title") == 0) {
		return TITLE;
	}

	if(str.compare("creator") == 0) {
		return CREATOR;
	}

	if(str.compare("subject") == 0) {
		return SUBJECT;
	}

	if(str.compare("description") == 0) {
		return DESCRIPTION;
