	inline ustring __create_text(const ustring & nodename, const ustring & nodecontents)
	{
		ustring tmp;
		tmp += "<";
		tmp += nodename;
		tmp += ">";
		tmp += nodecontents;
		tmp += "</";
		tmp += nodename;
		tmp += ">";
		return tmp;
	}

