						ustring cname = attribute->get_value();
						CSSClass tmp = classes.get_class(cname);
						cssclass.add(tmp);
					}
					*/
				}

				pair<ustring, ustring> content = __recursive_strip(items, css, file, ntmp);

				if(ct != HR && content.first.empty()) {
					continue;
				}

				#ifdef DEBUG
				cout << tmpnode->get_name()  << " " << __id << endl;
