CSS::CSS(CSS const & cpy) :
	files(cpy.files),
	rules(cpy.rules)
{
}

CSS::CSS(CSS && mv) :
	files(move(mv.files)),
	rules(move(mv.rules))
{
}

CSS & CSS::operator =(const CSS & cpy)
{
	files = cpy.files;
	rules = cpy.rules;
	return *this;
}

CSS & CSS::operator =(CSS && mv)
{
	files = move(mv.files);
	rules = move(mv.rules);
	return *this;
}

CSS::~CSS() { }

CSSRule CSS::get_rule(const ustring & _selector) const
{

	for(auto & rule : rules) {
		if(rule.selector.matches(_selector)) {
			return rule;
		}
	}

	//It doesn't exist in the database. Return a CSSRule with all defaults.
	return CSSRule();

}

bool CSS::contains_rule(const ustring & _selector) const
{

	if(rules.size() == 0) {
		return false;
	}

	for(auto & rule : rules) {
		if(rule.selector.matches(_selector)) {
			return true;
		}
	}

	return false;

}

